mapper.select:
select 
from text_to_sql_run


        and source_type = #{sourceType}


        and (
            original_question like concat('%', #{keyword}, '%')
            or final_question like concat('%', #{keyword}, '%')
            or final_answer like concat('%', #{keyword}, '%')
        )


        and conversation_id like concat('%', #{conversationId}, '%')


        and question_type = #{questionType}


        and business_id = #{businessId}


        and status = #{status}


        and sql_action = #{sqlAction}


        and feedback_result = #{feedbackResult}


        and (
            case
                when interrupted = 1 then 1
                when json_length(json_extract(state_snapshot_json, '$.clarification_history')) > 0 then 1
                else 0
            end
        ) = #{interrupted}


order by id desc
